// shared/src/systems/layout/helpers.ts
function distributeAligned(count, containerSize, itemSize, spacing, align, padding) {
  if (count <= 0) return [];
  if (count === 1) return [0];
  const usableSize = containerSize - 2 * padding;
  const halfContainer = containerSize / 2;
  if (spacing === "auto") {
    switch (align) {
      case "space-evenly": {
        const totalItemSize = count * itemSize;
        const totalGapSpace = usableSize - totalItemSize;
        const gap = totalGapSpace / (count + 1);
        return Array.from(
          { length: count },
          (_, i) => -halfContainer + padding + gap + itemSize / 2 + i * (itemSize + gap)
        );
      }
      case "space-between": {
        if (count === 1) return [0];
        const totalItemSize = count * itemSize;
        const totalGapSpace = usableSize - totalItemSize;
        const gap = totalGapSpace / (count - 1);
        return Array.from(
          { length: count },
          (_, i) => -halfContainer + padding + itemSize / 2 + i * (itemSize + gap)
        );
      }
      case "center": {
        const defaultSpacing = itemSize * 0.2;
        const totalWidth = count * itemSize + (count - 1) * defaultSpacing;
        const startPos = -totalWidth / 2 + itemSize / 2;
        return Array.from(
          { length: count },
          (_, i) => startPos + i * (itemSize + defaultSpacing)
        );
      }
      case "start": {
        const defaultSpacing = itemSize * 0.2;
        return Array.from(
          { length: count },
          (_, i) => -halfContainer + padding + itemSize / 2 + i * (itemSize + defaultSpacing)
        );
      }
      case "end": {
        const defaultSpacing = itemSize * 0.2;
        const totalWidth = count * itemSize + (count - 1) * defaultSpacing;
        return Array.from(
          { length: count },
          (_, i) => halfContainer - padding - totalWidth + itemSize / 2 + i * (itemSize + defaultSpacing)
        );
      }
    }
  } else {
    const fixedSpacing = spacing;
    const totalWidth = count * itemSize + (count - 1) * fixedSpacing;
    switch (align) {
      case "center":
      case "space-evenly":
      case "space-between": {
        const startPos = -totalWidth / 2 + itemSize / 2;
        return Array.from(
          { length: count },
          (_, i) => startPos + i * (itemSize + fixedSpacing)
        );
      }
      case "start": {
        return Array.from(
          { length: count },
          (_, i) => -halfContainer + padding + itemSize / 2 + i * (itemSize + fixedSpacing)
        );
      }
      case "end": {
        return Array.from(
          { length: count },
          (_, i) => halfContainer - padding - totalWidth + itemSize / 2 + i * (itemSize + fixedSpacing)
        );
      }
    }
  }
  return [];
}
function distributeRow(config) {
  const {
    count,
    containerWidth,
    itemWidth = 1,
    spacing = "auto",
    align = "space-evenly",
    padding = 0,
    centerY = 0
  } = config;
  const xPositions = distributeAligned(
    count,
    containerWidth,
    itemWidth,
    spacing,
    align,
    padding
  );
  return xPositions.map((x, index) => ({
    x,
    y: centerY,
    index
  }));
}

